import fs from 'fs/promises';
import path from 'path';
import { z } from 'zod';
import { errnoCode } from '../../utils/errnoCode';
import { writeFileAtomic } from '../../utils/writeFileAtomic';

const PreviewSchema = z.object({
  sourceKey: z.string(),
  projectPath: z.string(),
  dataUrl: z.string().startsWith('data:image/jpeg;base64,'),
  label: z.string(),
  capturedAt: z.string().datetime(),
});
export type CachedProjectPreview = z.infer<typeof PreviewSchema>;
const OWNER_ONLY_DIRECTORY = 0o700;
const OWNER_ONLY_FILE = 0o600;

export class ProjectPreviewCache {
  constructor(private readonly root: string) {}

  async read(projectId: string): Promise<CachedProjectPreview | null> {
    try {
      const raw: unknown = JSON.parse(
        await fs.readFile(this.file(projectId), 'utf8'),
      );
      const result = PreviewSchema.safeParse(raw);
      return result.success ? result.data : null;
    } catch (error) {
      if (error instanceof SyntaxError || errnoCode(error) === 'ENOENT')
        return null;
      throw error;
    }
  }

  async write(projectId: string, preview: CachedProjectPreview): Promise<void> {
    const target = this.file(projectId);
    await fs.mkdir(path.dirname(target), {
      recursive: true,
      mode: OWNER_ONLY_DIRECTORY,
    });
    await writeFileAtomic(
      target,
      JSON.stringify(PreviewSchema.parse(preview)),
      {
        mode: OWNER_ONLY_FILE,
      },
    );
  }

  private file(projectId: string): string {
    return path.join(
      this.root,
      'cache',
      z.string().uuid().parse(projectId),
      'project-preview.json',
    );
  }
}
